import type { BankQuestion } from "@/lib/bank";

/** Taxation & Business Law (Management & Commerce): 175 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-tax-law-1","question":"A registered supplier in Maharashtra sells goods to a buyer in Maharashtra, and the goods are delivered within Maharashtra. Which GST applies?","options":["CGST + SGST","IGST","Only CGST","Only SGST"],"answer":0,"explanation":"Supplier and place of supply are in the same state, so it is an intra-state supply, taxed half as CGST and half as SGST.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-2","question":"A supplier in Delhi sells goods to a buyer in Jaipur, and the goods move from Delhi to Jaipur. Which GST applies?","options":["CGST + SGST of Delhi","CGST + SGST of Rajasthan","IGST","No GST, as it is a stock transfer"],"answer":2,"explanation":"The supplier is in Delhi and the place of supply (where movement ends) is Rajasthan, so it is an inter-state supply attracting IGST.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-3","question":"The list price of goods is ₹1,00,000. A 5% trade discount on the list price is shown on the invoice; packing charged separately is ₹2,000 and freight charged by the supplier for delivering the goods is ₹3,000. What is the taxable value?","options":["₹1,00,000","₹1,05,000","₹95,000","₹97,000"],"answer":0,"explanation":"The discount shown on the invoice at the time of supply is excluded: 95,000. Packing and freight charged by the supplier are incidental and included: 95,000 + 2,000 + 3,000 = ₹1,00,000.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-4","question":"A supplier sells goods for ₹50,000 (excluding GST). It also receives a subsidy of ₹5,000 from a private trust, directly linked to this sale's price, and charges ₹1,000 interest for late payment. What is the taxable value?","options":["₹50,000","₹55,000","₹56,000","₹51,000"],"answer":2,"explanation":"Value includes subsidies directly linked to price unless given by the Central or State Government, and also interest or late fees for delayed payment: 50,000 + 5,000 + 1,000 = ₹56,000.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-5","question":"Three months after a sale, a supplier decides to give the customer a 5% discount that was not provided for in any agreement made before the supply. Under GST:","options":["The taxable value can be reduced through a GST credit note","The discount cannot reduce the taxable value; only a commercial (financial) credit note can be issued","The government refunds the tax on the discount","The customer's ITC rises by the discount"],"answer":1,"explanation":"A post-supply discount reduces value only if it was agreed before or at the time of supply, is linked to specific invoices and the recipient reverses the matching ITC. An unplanned later discount does not qualify.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-6","question":"For a month, output tax is IGST ₹50,000, CGST ₹30,000 and SGST ₹30,000. Input tax credit available is IGST ₹70,000, CGST ₹10,000 and SGST ₹15,000. What is the minimum cash payment needed?","options":["₹35,000","₹15,000","₹20,000","₹25,000"],"answer":1,"explanation":"IGST credit is used first: ₹50,000 against IGST, and the remaining ₹20,000 against CGST/SGST in any proportion. If at least ₹5,000 goes to SGST, no credit is stranded: total output 1,10,000 − total credit 95,000 = ₹15,000 cash. Using IGST credit only against IGST leaves ₹35,000 to pay.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-7","question":"Which of these set-offs of input tax credit is NOT allowed under GST?","options":["IGST credit against CGST liability","CGST credit against IGST liability","SGST credit against IGST liability","CGST credit against SGST liability"],"answer":3,"explanation":"CGST and SGST belong to different governments, so neither credit can pay the other. Both can pay IGST, and IGST credit can pay either.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-8","question":"A company receives legal services worth ₹2,00,000 from an advocate, on which GST is payable under reverse charge at 18% (assume). Its electronic credit ledger has ₹1,00,000. How does it discharge the liability?","options":["Pay ₹36,000 in cash, then claim ₹36,000 as input tax credit","Set off ₹36,000 from the credit ledger","Nothing: the advocate pays the tax","Pay ₹36,000 in cash with no input tax credit allowed"],"answer":0,"explanation":"Tax under reverse charge must be paid through the cash ledger, not from existing credit. Once paid, it is available as ITC if the service is used in the business.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-9","question":"A, registered in Gujarat, orders goods from S in Maharashtra and asks S to deliver them directly to C, also in Maharashtra; S bills A. What tax does S charge A?","options":["CGST + SGST of Maharashtra, as the goods move within Maharashtra","IGST, as the place of supply is A's principal place of business in Gujarat","No GST, as the goods never leave Maharashtra","CGST + SGST of Gujarat"],"answer":1,"explanation":"In a bill-to-ship-to supply, the place of supply for S's sale is the principal place of business of the person on whose direction the goods are delivered (A, Gujarat). Supplier in Maharashtra + place of supply in Gujarat = IGST.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-10","question":"A shop sells a festival hamper of sweets, dry fruits and a packaged juice for one price. Sold separately, the items would attract 5%, 12% and 18% (assume these rates). How is the hamper taxed?","options":["As a composite supply at 5%, the rate of the main item","Each item at its own rate on an apportioned price","As a mixed supply at 18% on the whole price","At the average of the three rates"],"answer":2,"explanation":"The items are not naturally bundled (each is sold on its own), so it is a mixed supply, taxed at the highest rate applicable to any item in it.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-11","question":"Which statement about a supplier of goods under the GST composition scheme is correct?","options":["It can charge GST separately on its invoices","It cannot claim input tax credit and cannot collect tax from customers","It can freely make inter-state outward supplies","It must issue tax invoices"],"answer":1,"explanation":"A composition taxpayer pays tax on turnover out of its own pocket, issues a bill of supply, cannot collect tax from buyers, cannot take ITC and cannot make inter-state outward supplies of goods.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-12","question":"How many statements about a composition taxpayer supplying goods are correct? (1) It issues a bill of supply, not a tax invoice. (2) It can claim input tax credit on its purchases. (3) It cannot make inter-state outward supplies of goods. (4) It pays tax on its reverse-charge inward supplies at normal rates, without input tax credit.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (3) and (4) are correct. (2) is wrong: a composition taxpayer cannot claim ITC on any purchase.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-13","question":"In which case is input tax credit allowed?","options":["A 30-seater bus bought by a factory to carry its workers","Outdoor catering for an employees' party that no law requires","Club membership for the company's directors","Goods given away as free samples"],"answer":0,"explanation":"The block on motor vehicles covers only vehicles for carrying persons with a seating capacity of up to 13 (including the driver), so a 30-seater bus qualifies. Catering not required by law, club membership and free samples are blocked under Section 17(5).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-14","question":"For which of these is input tax credit allowed?","options":["Works contract for constructing the company's office building","Works contract for installing plant and machinery","Cement used to build the factory's boundary wall","Repairs capitalised to the office building"],"answer":1,"explanation":"Works contracts and goods for constructing immovable property are blocked, except for plant and machinery. A boundary wall and an office building are civil structures, not plant and machinery.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-15","question":"Assertion (A): A company that claims income-tax depreciation on the full cost of a machine including its ₹1,80,000 GST cannot also take ₹1,80,000 as input tax credit. Reason (R): The GST law denies input tax credit on the tax component of capital goods when depreciation is claimed on that tax component.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Section 16(3) prevents a double benefit: tax cannot be both capitalised for depreciation and claimed as credit. That rule is exactly what A applies.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-16","question":"A recipient takes input tax credit but does not pay the supplier the value and tax within 180 days of the invoice. What happens?","options":["The credit must be reversed (added to output tax) with interest, and can be re-claimed once payment is made","The credit is lost permanently","Nothing, since the supplier has paid the tax","The supplier must refund the tax to the buyer"],"answer":0,"explanation":"The proviso to Section 16(2) requires payment within 180 days; otherwise the credit is reversed with interest, and it can be taken again when the payment is made.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-17","question":"Which of these is a supply under GST even though no consideration is received?","options":["Permanent transfer of business machinery, on which ITC was claimed, to the owner's relative","Distribution of free samples on which no ITC was claimed","A donation received by a charity","Salary paid to an employee"],"answer":0,"explanation":"Schedule I treats the permanent transfer or disposal of business assets on which ITC was availed as a supply even without consideration. Salary is outside GST (employee services, Schedule III).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-18","question":"A business has taxable intra-state supplies of ₹40 lakh, exempt supplies of ₹10 lakh and exports of ₹15 lakh. It also received inward supplies of ₹5 lakh on which it paid tax under reverse charge, and it charged GST of ₹7.2 lakh on its taxable supplies. What is its aggregate turnover?","options":["₹70 lakh","₹65 lakh","₹72.2 lakh","₹55 lakh"],"answer":1,"explanation":"Aggregate turnover includes taxable, exempt and export supplies (40 + 10 + 15 = ₹65 lakh) but excludes inward supplies under reverse charge and the taxes themselves.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-19","question":"A Karnataka supplier makes intra-state sales of ₹10,00,000 and inter-state sales of ₹5,00,000, all at 18% (assume). Its input tax credit is IGST of ₹1,50,000 only. How much does it pay in cash?","options":["₹1,80,000","₹2,70,000","₹1,20,000","₹1,50,000"],"answer":2,"explanation":"Output: CGST 90,000 + SGST 90,000 + IGST 90,000 = 2,70,000. IGST credit pays IGST 90,000 and the balance 60,000 goes to CGST/SGST. Cash = 2,70,000 − 1,50,000 = ₹1,20,000. Using IGST credit only against IGST leaves ₹1,80,000 to pay.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-20","question":"Exports are zero-rated under GST. How can an exporter handle them?","options":["Only by paying IGST and claiming a refund","Only under a letter of undertaking, with no refund of input tax credit","Either export under a letter of undertaking without paying IGST and claim a refund of unused ITC, or pay IGST and claim its refund","Exports are exempt, so the related ITC must be reversed"],"answer":2,"explanation":"Zero-rating keeps the exporter's ITC alive through either route. Exempt supplies, by contrast, require ITC reversal.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-21","question":"Which of these is a composite supply?","options":["Goods sold with packing, transport and insurance for a single price","A hamper of chocolates and a water bottle sold for one price","Two unrelated products sold as a combo offer","A gift box of dry fruits and a wristwatch"],"answer":0,"explanation":"In a composite supply the items are naturally bundled and supplied together in the ordinary course of business, with one principal supply (here the goods). The others are mixed supplies.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-22","question":"A company pays sitting fees to an independent director who is not its employee, and salary to its whole-time director who is an employee. Which is correct?","options":["Both are supplies and the directors charge GST","Neither is within GST","The company pays GST under reverse charge on the sitting fees; the employee director's salary is not a supply","The employee director's salary attracts GST under reverse charge"],"answer":2,"explanation":"Services by a director to the company are under reverse charge, so the company pays tax on the sitting fees. Services by an employee to the employer in the course of employment are outside GST (Schedule III).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-23","question":"GST is best described as:","options":["An origin-based tax on production","A destination-based tax on consumption","A direct tax on income","A tax on goods only"],"answer":1,"explanation":"GST accrues to the state where the goods or services are consumed, with credit at every stage so that only value addition is taxed.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-24","question":"Which of these was NOT subsumed into GST?","options":["Central excise duty on most goods","Service tax","Basic customs duty","State VAT"],"answer":2,"explanation":"Basic customs duty on imports continues separately; IGST is levied on imports in addition. Excise (except on certain items such as petroleum and tobacco), service tax and VAT were subsumed.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-25","question":"A supplier in Tamil Nadu sells goods to an SEZ unit located in Tamil Nadu. How is the supply treated under GST?","options":["As an intra-state supply attracting CGST + SGST","As an exempt supply with ITC reversal","As a non-taxable supply outside GST","As an inter-state, zero-rated supply (IGST with refund, or under a letter of undertaking)"],"answer":3,"explanation":"The IGST Act treats a supply to an SEZ developer or unit as inter-state even when both are in the same state, and it is zero-rated.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-26","question":"The price of an article, inclusive of GST at 18% (assume), is ₹11,800. How much GST is included in it?","options":["₹2,124","₹1,800","₹1,180","₹1,416"],"answer":1,"explanation":"Tax = 11,800 × 18/118 = ₹1,800 on a value of ₹10,000. Taking 18% of the tax-inclusive price gives ₹2,124.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-27","question":"Common inputs carry input tax credit of ₹1,00,000. In the period, taxable turnover is ₹60 lakh and exempt turnover ₹40 lakh. How much credit must be reversed?","options":["₹40,000","₹60,000","₹66,667","Nil"],"answer":0,"explanation":"Credit on common inputs is reversed in the ratio of exempt turnover to total turnover: 1,00,000 × 40/100 = ₹40,000. Dividing by taxable turnover instead gives ₹66,667.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-28","question":"A company holds GST registrations in Karnataka and Kerala under the same PAN. Which is correct?","options":["Both form one taxable person, so transfers between them are not supplies","Each registration is a distinct person, and a stock transfer between them is a supply even without consideration","Only services between them are supplies","Transfers between them are exempt"],"answer":1,"explanation":"Separate registrations of the same PAN are distinct persons, and Schedule I treats supplies between distinct persons in the course of business as supplies even without consideration.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-29","question":"An architect registered in Mumbai designs a building to be built in Pune for a client registered in Delhi. What tax does the architect charge?","options":["IGST, as the client is in Delhi","CGST + SGST of Delhi","No GST, as immovable property is outside GST","CGST + SGST of Maharashtra, as the place of supply is where the property is"],"answer":3,"explanation":"For services directly related to immovable property, including architects' services, the place of supply is the location of the property (Maharashtra). The supplier is also in Maharashtra, so it is intra-state. Using the general B2B rule (recipient's location) wrongly gives IGST.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-30","question":"Which of these is treated as neither a supply of goods nor a supply of services?","options":["Sale of a building after its completion certificate has been issued","Sale of old office furniture by a company","Renting of a commercial shop","Transfer of stock between registrations of the same company in different states"],"answer":0,"explanation":"Schedule III excludes the sale of land and of a building after its completion certificate. Renting is a supply of services; selling business assets and inter-state stock transfers are supplies.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-31","question":"Which of these is NOT one of the five heads of income under Indian income tax?","options":["Salaries","Income from house property","Capital gains","Income from investments"],"answer":3,"explanation":"The five heads are salaries, house property, profits and gains of business or profession, capital gains and income from other sources. Investment income falls under one of these (usually other sources or capital gains).","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-32","question":"Assume the basic rule: an individual is resident if in India for 182 days or more in the year, or for 60 days or more in the year and 365 days or more in the four preceding years. Mr X, a foreign citizen, was in India for 70 days this year and 400 days in the four preceding years. What is his status?","options":["Non-resident, because he is a foreign citizen","Non-resident, because he stayed less than 182 days","Resident, under the 60-day + 365-day test","Resident only for income received in India"],"answer":2,"explanation":"Residence depends on physical presence, not citizenship. 70 ≥ 60 and 400 ≥ 365, so the second condition is met and he is resident.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-33","question":"Assume the basic residence tests (182 days; or 60 days in the year plus 365 days in the four preceding years), and that for an Indian citizen who leaves India during the year for employment abroad the 60-day figure is replaced by 182 days. Ms Y, an Indian citizen, leaves for a job abroad after spending 150 days in India this year; she was in India throughout the four preceding years. What is her status?","options":["Resident, because she is an Indian citizen","Resident, because of more than 365 days in the preceding four years","Resident but only for Indian income","Non-resident, because she was in India for less than 182 days"],"answer":3,"explanation":"For a citizen leaving for employment, the relaxed 60-day test does not apply; she needs 182 days. With 150 days she fails both tests and is non-resident, whatever her past stay.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-34","question":"Mr Z is non-resident this year. How many of these are taxable in India in his hands? (1) Salary for work done in India, credited to his Dubai account (2) Profits of a business controlled from abroad, earned and received abroad (3) Interest on a savings account with an Indian bank (4) Rent from a house in London, received in London","options":["One","Two","Three","Four"],"answer":1,"explanation":"A non-resident is taxed only on income received, or accruing or arising, in India. (1) accrues in India because the work is done here; (3) arises in India. (2) and (4) are foreign income received abroad. Two are taxable.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-35","question":"A let-out house has a gross annual value of ₹3,60,000. The owner paid municipal taxes of ₹30,000 and interest of ₹1,00,000 on a loan taken to buy it. Assume a standard deduction of 30% of net annual value. What is the income from house property?","options":["₹1,52,000","₹2,31,000","₹1,22,000","₹1,31,000"],"answer":3,"explanation":"Net annual value = 3,60,000 − 30,000 = 3,30,000. Standard deduction 30% = 99,000 → 2,31,000. Less interest 1,00,000 = ₹1,31,000. Taking 30% of the gross value instead (and ignoring taxes) gives ₹1,52,000.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-36","question":"Take expected rent as the higher of municipal value and fair rent, but not more than the standard rent under rent-control law; gross annual value is the higher of expected rent and actual rent received. Municipal value ₹2,40,000; fair rent ₹2,70,000; standard rent ₹2,60,000; actual rent received ₹2,50,000. What is the gross annual value?","options":["₹2,70,000","₹2,50,000","₹2,60,000","₹2,40,000"],"answer":2,"explanation":"Higher of municipal value and fair rent = 2,70,000, capped at standard rent → expected rent 2,60,000. GAV = higher of 2,60,000 and actual rent 2,50,000 = ₹2,60,000. Forgetting the standard-rent cap gives ₹2,70,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-37","question":"For a self-occupied house, assume annual value is nil, interest deduction is capped at ₹2,00,000, and pre-construction interest is allowed in five equal instalments starting from the year construction is completed. Pre-construction interest was ₹1,50,000 and interest for the current year (the year of completion) is ₹1,80,000. What is the income from house property?","options":["Loss of ₹2,00,000","Loss of ₹2,10,000","Loss of ₹3,30,000","Loss of ₹1,80,000"],"answer":0,"explanation":"Interest allowable = 1,50,000 ÷ 5 + 1,80,000 = 2,10,000, but the cap limits it to 2,00,000. With nil annual value, the loss is ₹2,00,000. Claiming all the pre-construction interest at once gives ₹3,30,000.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-38","question":"Under a regime that allows HRA exemption, assume the exemption is the least of: HRA received; rent paid minus 10% of salary; and 50% of salary (metro city). Salary (for this purpose) is ₹6,00,000, HRA received ₹1,80,000 and rent paid ₹2,10,000 in a metro city. What is the exempt HRA?","options":["₹1,80,000","₹1,50,000","₹3,00,000","₹30,000"],"answer":1,"explanation":"The three limits are 1,80,000; 2,10,000 − 60,000 = 1,50,000; and 3,00,000. The least is ₹1,50,000, so ₹30,000 of the HRA is taxable.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-39","question":"Land is sold for ₹50,00,000, but its stamp duty value is ₹56,00,000. Assume that if the stamp duty value exceeds the consideration by more than 10%, the stamp duty value is taken as the sale consideration. Cost of acquisition (no indexation) is ₹30,00,000 and brokerage is 1% of the actual sale price. What is the capital gain?","options":["₹19,50,000","₹26,00,000","₹20,00,000","₹25,50,000"],"answer":3,"explanation":"110% of 50,00,000 = 55,00,000, and 56,00,000 exceeds it, so consideration = 56,00,000. Brokerage = 50,000. Gain = 56,00,000 − 30,00,000 − 50,000 = ₹25,50,000. Using the actual price gives ₹19,50,000.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-40","question":"Property is sold for ₹80,00,000; its stamp duty value is ₹87,00,000. Assume the stamp duty value replaces the consideration only if it exceeds the consideration by more than 10%. Cost of acquisition is ₹45,00,000, cost of improvement ₹5,00,000 and transfer expenses ₹1,00,000 (no indexation). What is the capital gain?","options":["₹36,00,000","₹29,00,000","₹34,00,000","₹30,00,000"],"answer":1,"explanation":"110% of 80,00,000 = 88,00,000; 87,00,000 does not exceed it, so the actual ₹80,00,000 is used. Gain = 80,00,000 − 45,00,000 − 5,00,000 − 1,00,000 = ₹29,00,000. Using the stamp duty value gives ₹36,00,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-41","question":"Which set-off of losses is permitted?","options":["Long-term capital loss against short-term capital gain","Business loss against salary income","Speculation business loss against non-speculation business income","Short-term capital loss against long-term capital gain"],"answer":3,"explanation":"A short-term capital loss can be set off against both short-term and long-term gains, but a long-term capital loss only against long-term gains. Business losses cannot be set off against salary, and speculation losses only against speculation income.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-42","question":"An individual has salary income of ₹8,00,000, a loss from house property of ₹2,50,000, business income of ₹1,00,000, a short-term capital gain of ₹50,000 and a long-term capital loss of ₹70,000. Assume a house-property loss can be set off against other heads only up to ₹2,00,000. What is the gross total income?","options":["₹7,50,000","₹7,00,000","₹6,50,000","₹8,00,000"],"answer":0,"explanation":"8,00,000 − 2,00,000 (capped HP loss) + 1,00,000 + 50,000 STCG = ₹7,50,000. The long-term capital loss cannot be set off against the short-term gain and is carried forward, as is ₹50,000 of the HP loss.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-43","question":"Which of these is agricultural income?","options":["Income from poultry farming","Dividend from a tea-plantation company","Rent received from agricultural land in India used for agriculture","Sale of trees that grew naturally, without any cultivation"],"answer":2,"explanation":"Rent or revenue from agricultural land in India used for agriculture is agricultural income. Poultry is not agriculture, a dividend is from a company, and naturally grown trees involve no agricultural operations.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-44","question":"A company credits a consultant's professional fees to his account in its books on 31 March and pays him on 15 April. For a TDS provision that applies at credit or payment, whichever is earlier, when must tax be deducted?","options":["On 15 April, when the cash is paid","When the consultant raises his invoice","At the end of the following quarter","On 31 March, when the amount is credited"],"answer":3,"explanation":"Under the 'credit or payment, whichever is earlier' rule, crediting the payee's account (including a suspense or provision account) triggers deduction, so TDS is due on 31 March.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-45","question":"A business paid a resident contractor ₹10,00,000 without deducting the TDS that was due. Its profit before this adjustment is ₹25,00,000. Assume 30% of an expense is disallowed when TDS is not deducted, and that the disallowed amount is allowed in the year the TDS is later deducted and paid. What is its business income this year?","options":["₹25,00,000","₹28,00,000","₹35,00,000","₹22,00,000"],"answer":1,"explanation":"Disallowance = 30% × 10,00,000 = 3,00,000, added back: 25,00,000 + 3,00,000 = ₹28,00,000. The ₹3,00,000 becomes deductible in the year the TDS is paid. Disallowing the whole expense gives ₹35,00,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-46","question":"Tax deducted at source (TDS) is best described as:","options":["A penalty for late filing","A tax on exempt income","An additional tax over and above the regular tax","A way of collecting tax at the point where income is paid, credited against the payee's final liability"],"answer":3,"explanation":"The payer deducts tax and deposits it; the payee claims it as a credit when computing final tax.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-47","question":"Which statement about advance tax is correct?","options":["It is paid after the year ends, along with the return","It is a tax on future income of the next year","It is paid in instalments during the same year in which the income is earned","It applies only to companies"],"answer":2,"explanation":"Advance tax ('pay as you earn') is paid in instalments during the year itself when estimated liability crosses the threshold; shortfalls attract interest.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-48","question":"Mr A gifts ₹10 lakh to his wife without adequate consideration. She invests it in a fixed deposit and earns ₹80,000 interest, which she reinvests and earns ₹6,000 more. Under the clubbing rules, what is included in Mr A's income?","options":["₹86,000","Nil, because a gift to a spouse is exempt","₹6,000","₹80,000"],"answer":3,"explanation":"Income from assets transferred to a spouse without adequate consideration is clubbed with the transferor's income: the ₹80,000. Income earned on that clubbed income (the ₹6,000 on reinvested interest) is not clubbed; it is the wife's income.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-49","question":"A proprietor's profit and loss account shows a net profit of ₹12,00,000 after debiting income tax of ₹2,00,000, book depreciation of ₹1,50,000 and personal expenses of ₹30,000, and after crediting dividend income of ₹50,000 (taxed under another head). Tax depreciation allowable is ₹1,80,000. What is the business income?","options":["₹14,00,000","₹13,80,000","₹12,90,000","₹13,50,000"],"answer":3,"explanation":"12,00,000 + 2,00,000 (income tax) + 1,50,000 (book depreciation) − 1,80,000 (tax depreciation) − 50,000 (dividend) + 30,000 (personal expenses) = ₹13,50,000. Leaving the dividend in gives ₹14,00,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-50","question":"Which of these is taxed under 'Income from other sources'?","options":["Interest on a bank fixed deposit held as an investment by a salaried person","Rent from a let-out flat","Gain on sale of shares held as investments","Salary arrears"],"answer":0,"explanation":"Interest income not chargeable under another head goes to other sources. Rent from a building is house property, share gains are capital gains and arrears are salary.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-51","question":"Assume that gifts of money from non-relatives are fully taxable if their aggregate in the year exceeds ₹50,000, while gifts from relatives are exempt. During the year Ms P receives ₹80,000 from a friend and ₹2,00,000 from her brother. How much is taxable?","options":["₹30,000","₹80,000","₹2,80,000","Nil"],"answer":1,"explanation":"The brother is a relative, so ₹2,00,000 is exempt. Gifts from non-relatives total ₹80,000, which exceeds ₹50,000, so the whole ₹80,000 (not just the excess of ₹30,000) is taxable.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-52","question":"Which statement correctly distinguishes tax planning, tax avoidance and tax evasion?","options":["All three are legal","Tax evasion is legal if disclosed later","Tax planning uses provisions as the law intends; avoidance exploits loopholes against the law's intent; evasion is illegal concealment","Tax planning and tax evasion mean the same thing"],"answer":2,"explanation":"Planning (e.g. claiming eligible deductions) is legitimate; avoidance is technically within the letter but against the spirit and can be countered by anti-avoidance rules; evasion (suppressing income, false expenses) is a crime.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-53","question":"How is the residential status of a company determined?","options":["By the residence of the majority of its shareholders","By where most of its sales are made","By the citizenship of its directors","An Indian company is always resident; a foreign company is resident if its place of effective management is in India"],"answer":3,"explanation":"Incorporation in India makes a company resident every year; a foreign company becomes resident only if its place of effective management (where key management decisions are actually taken) is in India.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-54","question":"Mr Q is non-resident. His income: salary for work done in India, received in Dubai ₹5,00,000; interest from an Indian bank ₹50,000; rent from a house in London received in London ₹3,00,000; dividend from a US company received in the US ₹1,00,000. What is his income taxable in India?","options":["₹5,50,000","₹9,50,000","₹50,000","₹8,50,000"],"answer":0,"explanation":"A non-resident is taxed on income accruing or received in India: salary for Indian work (₹5,00,000) and Indian interest (₹50,000) = ₹5,50,000. The London rent and US dividend are foreign income received abroad. If he were an ordinarily resident, all ₹9,50,000 would be taxed.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-55","question":"A block of assets taxed at 15% has an opening WDV of ₹10,00,000. An asset costing ₹4,00,000 is added and put to use for less than 180 days; an asset from the block is sold for ₹2,00,000. Assume only half the rate is allowed on an asset used for less than 180 days in the year. What is the depreciation?","options":["₹1,80,000","₹1,65,000","₹1,50,000","₹1,20,000"],"answer":2,"explanation":"Deduct the sale from the opening WDV first: (10,00,000 − 2,00,000) × 15% = 1,20,000. New asset: 4,00,000 × 7.5% = 30,000. Total ₹1,50,000. Full rate on everything gives ₹1,80,000; netting the sale against the new asset instead gives ₹1,65,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-56","question":"A block of depreciable assets has a WDV of ₹3,00,000 at the start of the year, with no additions. The only asset in the block, held for many years, is sold for ₹5,00,000. How is the ₹2,00,000 excess treated?","options":["As a long-term capital gain, because the asset was held for many years","As business income of ₹5,00,000","No gain arises; the WDV simply becomes negative","As a short-term capital gain, whatever the holding period"],"answer":3,"explanation":"For assets in a block, when sale proceeds exceed the opening WDV plus additions, the excess is deemed a short-term capital gain regardless of how long the asset was held.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-57","question":"A company incurs ₹40,000 of expenses wholly to earn dividend income that is exempt in its hands. Can it deduct these expenses from its taxable income?","options":["Yes, all business expenses are deductible","No, expenses related to exempt income are not deductible","Yes, but only half","Only if the dividend exceeds the expenses"],"answer":1,"explanation":"Expenditure incurred in relation to income that does not form part of total income is not allowed as a deduction.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-58","question":"Assertion (A): A small business opting for presumptive taxation may declare income at a prescribed percentage of turnover without maintaining detailed books. Reason (R): Presumptive schemes aim to reduce compliance burden by deeming income on a simple base.","options":["Both A and R are false","A is true but R is false","Both A and R are true, and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Presumptive schemes deem income at a percentage of turnover or receipts precisely to spare small taxpayers detailed accounting and audit, which explains A.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-59","question":"The Permanent Account Number (PAN) is issued by:","options":["The Income Tax Department","The Reserve Bank of India","The GST Council","The Ministry of Corporate Affairs"],"answer":0,"explanation":"PAN is a ten-character alphanumeric identifier issued by the Income Tax Department.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-60","question":"Which of these is a direct tax?","options":["GST","Customs duty","Excise duty","Income tax"],"answer":3,"explanation":"A direct tax is borne by the person on whom it is levied. Income tax is direct; GST, customs and excise are indirect taxes passed on to consumers.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-61","question":"Goods displayed in a shop window with price tags are, in contract law:","options":["An invitation to offer","An offer","An acceptance","A binding promise"],"answer":0,"explanation":"A display invites customers to make offers; the customer offers to buy and the shopkeeper may accept or refuse.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-62","question":"Under the Indian Contract Act, a contract is:","options":["Any agreement between two persons","An agreement enforceable by law","Any promise made in writing","Any agreement involving money"],"answer":1,"explanation":"Section 2(h): an agreement enforceable by law is a contract. All contracts are agreements, but social or illegal agreements are not contracts.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-63","question":"A offers to sell his bike to B for ₹1,00,000. B replies that he will pay ₹90,000. A refuses. B then writes that he accepts the price of ₹1,00,000. A no longer wishes to sell. What is the legal position?","options":["There is a contract at ₹1,00,000, since B accepted A's price","There is a contract at ₹90,000","There is no contract: B's counter-offer rejected A's offer, and A made no fresh offer","There is a voidable contract"],"answer":2,"explanation":"A counter-offer is a rejection of the original offer, which then lapses. B's later 'acceptance' is only a fresh offer, which A may decline.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-64","question":"A writes to B offering his car for ₹5 lakh and adds: 'If I hear nothing from you by Friday, I shall treat the car as sold to you.' B does not reply. What is the position on Friday?","options":["A contract arises on Friday","B is bound, because he did not reject the offer","A contract arises if B privately intended to accept","No contract: the offeror cannot make silence count as acceptance"],"answer":3,"explanation":"Acceptance must be communicated by some act or words. An offeror cannot impose silence as acceptance on the offeree.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-65","question":"A posts an offer on 1 January, which B receives on 3 January. B posts his acceptance on 5 January; it reaches A on 8 January. B sends a revocation of his acceptance by courier, which reaches A on 7 January. What is the result?","options":["The revocation is valid, because it reached A before the acceptance did","The revocation is invalid, because the contract was concluded on 5 January","The revocation is invalid, because an acceptance can never be revoked","There is no contract, because A did not reply"],"answer":0,"explanation":"Acceptance is complete against the acceptor only when it comes to the proposer's knowledge (8 January), so B may revoke it until then. His revocation reached A on 7 January, so no contract arises.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-66","question":"How many of these statements are correct? (1) Communication of an offer is complete when it comes to the knowledge of the offeree. (2) Communication of an acceptance is complete against the proposer when it is put in the course of transmission. (3) Communication of an acceptance is complete against the acceptor when it comes to the knowledge of the proposer. (4) An offer can still be revoked after the acceptance has been posted, if the acceptance has not yet reached the proposer.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (3) state Section 4 correctly. (4) is wrong: an offer can be revoked only before the acceptance is put in the course of transmission against the proposer, i.e. before it is posted.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-67","question":"A company advertises a reward of ₹10,000 to anyone who finds its missing dog. X reads the advertisement, finds the dog and returns it, without first telling the company that he accepts. Can X claim the reward?","options":["No, because he did not communicate his acceptance first","Yes: performing the conditions of a general offer is acceptance","Only if the company agrees afterwards","No, because an offer made to the public cannot be accepted"],"answer":1,"explanation":"A general offer is accepted by anyone who performs its conditions with knowledge of it; separate communication of acceptance is not needed (the Carlill principle).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-68","question":"A servant traces his master's missing nephew. Only later does he learn that the master had announced a reward for finding the boy. Can he claim the reward?","options":["Yes, because he performed the act","Yes, but only half","Yes, once he learns of the reward","No, because an offer cannot be accepted by someone who does not know of it"],"answer":3,"explanation":"Acceptance requires knowledge of the offer. Doing the act in ignorance of the offer is not acceptance (Lalman Shukla v Gauri Dutt).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-69","question":"A woman gifts her property to her daughter on condition that the daughter pays an annual sum to the woman's brother. The daughter later refuses, arguing that the brother gave no consideration. Can the brother enforce the promise?","options":["Yes: consideration may move from the promisee or from any other person","No, because no consideration moved from him","No, because the gift is void","Only the woman can sue"],"answer":0,"explanation":"Under Section 2(d), consideration may move from the promisee 'or any other person'. The gift of property by the woman is consideration for the daughter's promise (Chinnaya v Ramayya).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-70","question":"At B's request, A repaired B's roof last year without fixing any price. B now promises to pay A ₹20,000. Is the promise enforceable?","options":["No, because past consideration is no consideration","Yes: in India, past consideration given at the promisor's request is valid","Only if the promise is written and registered","No, because it is a gratuitous promise"],"answer":1,"explanation":"Section 2(d) recognises an act already done ('has done') at the desire of the promisor as consideration. Indian law accepts past consideration, unlike English law.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-71","question":"Which of these agreements made without consideration are valid? (a) A father's written and registered promise, made out of natural love and affection, to give a house to his son (b) An oral promise to pay a time-barred debt (c) A promise to compensate a person who has already voluntarily paid a tax on the promisor's behalf (d) An unwritten promise to give someone a gift in future","options":["(a) only","(a), (b) and (c)","(a) and (c) only","All four"],"answer":2,"explanation":"Section 25 exceptions: (a) written, registered, natural love and affection between near relations; (c) compensation for something already done voluntarily for the promisor. A promise to pay a time-barred debt must be in writing and signed, so (b) fails; (d) has no exception.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-72","question":"A minor mortgages his house to a moneylender in return for a loan and later sues to have the mortgage cancelled. What is the legal position of the mortgage?","options":["Valid, since the minor received the money","Voidable at the lender's option","Valid once the minor repays the loan","Void from the beginning; the minor cannot be held liable on it"],"answer":3,"explanation":"An agreement with a minor is void ab initio (Mohori Bibee v Dharmodas Ghose), so the mortgage cannot be enforced against him.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-73","question":"How many of these statements about minors are correct? (1) A minor can be a promisee or beneficiary under a contract. (2) A minor can ratify an agreement on attaining majority. (3) A minor can act as an agent. (4) A minor can be admitted to the benefits of an existing partnership with the consent of all partners.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (3) and (4) are correct; the principal, not the minor agent, is bound in (3), and (4) is allowed by the Partnership Act. (2) is wrong: a void agreement cannot be ratified.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-74","question":"A person who is usually of unsound mind but occasionally of sound mind:","options":["Can never make a contract","May make a contract when he is of sound mind","Can contract only through a guardian","Can contract only for necessaries"],"answer":1,"explanation":"Section 12: a person usually of unsound mind but occasionally sound may contract when he is of sound mind; the reverse applies to a person usually sound but occasionally not.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-75","question":"C, a stranger to the deal, threatens to harm A's son unless A sells his car cheaply to B. B knows nothing of the threat. What is the status of the contract?","options":["Valid, because B did not use coercion","Void ab initio","Voidable at A's option, because coercion can come from any person","Illegal, so neither party can enforce it"],"answer":2,"explanation":"Coercion need not come from the other party, and it may be directed against anyone; it makes the contract voidable at the option of the party whose consent was so obtained.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-76","question":"A spiritual guru persuades a devotee to gift him most of her property. The devotee later challenges the gift. Which is correct?","options":["The gift is valid unless the devotee proves fraud","The gift is void because spiritual advisers cannot receive gifts","The gift is valid because gifts need no consideration","The gift is voidable, and the burden is on the guru to prove he did not use undue influence"],"answer":3,"explanation":"Where one party is in a position to dominate the will of the other (a spiritual adviser over a devotee) and the transaction looks unconscionable, undue influence is presumed and the dominant party must prove it was not used.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-77","question":"How many of these statements are correct? (1) Misrepresentation is an innocent false statement, while fraud is made knowingly or recklessly to deceive. (2) Both make the contract voidable at the option of the deceived party. (3) Mere silence about facts likely to affect consent is always fraud. (4) A contract is not voidable for misrepresentation if the party could have discovered the truth with ordinary diligence.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are correct. (3) is wrong: silence is fraud only where there is a duty to speak or the silence is itself equivalent to speech.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-78","question":"How many of these statements about mistake are correct? (1) If both parties are mistaken about a fact essential to the agreement, it is void. (2) A unilateral mistake of fact makes the contract voidable. (3) A contract is not voidable because of a mistake about a law in force in India. (4) A mistake about a foreign law is treated like a mistake of fact.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1) Section 20, (3) Section 21 and (4) its proviso are correct. (2) is wrong: under Section 22 a unilateral mistake of fact does not make a contract voidable.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-79","question":"Which of these agreements is void?","options":["An agreement in restraint of the marriage of an adult","An agreement made with a pardanashin woman","An agreement made under coercion","An agreement to sell goods on credit"],"answer":0,"explanation":"Section 26 makes agreements in restraint of the marriage of any person other than a minor void. Coercion makes a contract voidable, not void.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-80","question":"A sells the goodwill of his business to B and agrees not to carry on a similar business within the same city for three years. Is the restraint enforceable?","options":["No, every agreement in restraint of trade is void","Yes, if the limits are reasonable, because sale of goodwill is an exception to the rule","Only if registered","Only if B pays extra consideration for it"],"answer":1,"explanation":"Section 27 makes restraints of trade void, but its exception allows a seller of goodwill to agree not to compete within specified local limits, so long as they are reasonable.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-81","question":"Which of these clauses in a commercial contract are valid? (1) Future disputes will be referred to arbitration. (2) A party's rights are extinguished unless he sues within three months. (3) Only the courts of Mumbai, which have jurisdiction, will hear disputes. (4) Neither party may approach any court at all.","options":["(1) and (3) only","(1), (2) and (3)","(1) only","All four"],"answer":0,"explanation":"Section 28 voids agreements that absolutely restrict legal proceedings or extinguish rights on a shortened period. Arbitration clauses and choosing one of several competent courts are allowed.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-82","question":"Consent is NOT free when it is caused by:","options":["Advertisement","Negotiation","Coercion","Discount"],"answer":2,"explanation":"Coercion, undue influence, fraud, misrepresentation and mistake prevent consent from being free.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-83","question":"A agrees to pay B ₹1 lakh if B marries C. C dies before any marriage. What happens to the agreement?","options":["B can claim the money","It becomes voidable at A's option","A must pay half","It becomes void, because the event has become impossible"],"answer":3,"explanation":"A contingent contract to do something if an uncertain event happens becomes void when that event becomes impossible (Section 32).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-84","question":"A promises to pay B ₹5 lakh if a certain ship does not return within a year. The ship sinks six months later. Can B enforce the promise now?","options":["Yes, because it is now certain that the ship will not return within the year","No, he must wait until the year ends","No, the contract is void","Only if the ship was insured"],"answer":0,"explanation":"Under Section 35, a contract contingent on an event not happening within a fixed time can be enforced when the time expires or when it becomes certain before then that the event will not happen.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-85","question":"Assertion (A): A contract of insurance is not a wagering agreement. Reason (R): The insured has an insurable interest in the subject matter, and the contract protects against a real loss.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In a wager neither party has any interest other than the stake. Insurance is valid because the insured stands to suffer a genuine loss, which is what R says.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-86","question":"A agrees to pay a public servant ₹2 lakh to secure a government job for A's son. What is the status of the agreement?","options":["Valid, if the job is obtained","Voidable at A's option","Void, because its object is unlawful and opposed to public policy","Valid, but the money is refundable"],"answer":2,"explanation":"An agreement whose object involves corruption of public officers is unlawful under Section 23 and void.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-87","question":"A agrees to sell his house to B for ₹50 lakh, and further agrees that if B uses it as a gambling den, B will pay ₹1 crore. Which is correct?","options":["The whole agreement is void","Both promises are enforceable","Only the second promise is enforceable","The first set of promises (sale for ₹50 lakh) is enforceable; the second is void"],"answer":3,"explanation":"Section 57: where persons promise first to do legal things and then, in specified circumstances, illegal things, the first set is a contract and the second a void agreement.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-88","question":"How does an illegal agreement differ from an agreement that is merely void?","options":["They are identical in effect","An illegal agreement taints collateral transactions too, while transactions collateral to a merely void agreement may be valid","A void agreement can be ratified, but an illegal one cannot","An illegal agreement is valid until challenged"],"answer":1,"explanation":"Every illegal agreement is void, but not every void agreement is illegal. Agreements collateral to an illegal one are also void; those collateral to a merely void agreement can be enforced.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-89","question":"Which of these is NOT an exception to the rule that a stranger to a contract cannot sue on it?","options":["A creditor of one of the parties who hopes to be paid from the contract proceeds","A beneficiary under a trust","A person entitled under a family settlement","A person in whose favour a party has acknowledged an obligation (estoppel)"],"answer":0,"explanation":"Recognised exceptions include trusts, family settlements, acknowledgement or estoppel, covenants running with land and agency. A mere creditor of a party has no right to sue on the contract.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-90","question":"At an auction, a bidder makes the highest bid but withdraws it before the auctioneer's hammer falls. Which is correct?","options":["He is bound, because the highest bid is an acceptance","He is liable to pay damages","He can withdraw: each bid is an offer, and the sale is complete only when the hammer falls","He can withdraw only with the seller's consent"],"answer":2,"explanation":"In an auction the auctioneer invites offers; each bid is an offer that can be withdrawn until it is accepted by the fall of the hammer.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-91","question":"A finds a wallet lying on the road and takes it. What is his legal position with respect to the wallet?","options":["He becomes its owner","He is in the position of a bailee","He is the owner's agent","He becomes a trustee only after one year"],"answer":1,"explanation":"Under Section 71, a person who finds goods belonging to another and takes them into custody has the same responsibility as a bailee.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-92","question":"A delivers goods to B's house by mistake, intending no gift. B knows this and uses the goods. What is B's liability?","options":["None, because there was no contract","B must return only what remains unused","B must pay only if he signed for them","B must compensate A, because A acted non-gratuitously and B enjoyed the benefit"],"answer":3,"explanation":"Section 70: where a person lawfully does something for another, not intending to do so gratuitously, and the other enjoys the benefit, the latter must compensate or restore it.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-93","question":"A pays ₹40,000 to a municipality as property tax under the mistaken belief that he owes it; in fact the liability is B's. What can A do?","options":["Recover the money from the municipality, since money paid by mistake must be repaid","Nothing, as tax once paid cannot be recovered","Recover only half","Recover only if the municipality agrees"],"answer":0,"explanation":"Section 72: a person to whom money is paid by mistake or under coercion must repay or return it.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-94","question":"B holds land on lease from A. B fails to pay the government revenue due on it, and the land is advertised for sale. A pays the revenue to prevent the sale. What is A's right?","options":["None, because he paid voluntarily","He becomes owner of B's lease","He can recover the amount from B, as an interested person paying money another was bound to pay","He can recover it only from the government"],"answer":2,"explanation":"Section 69: a person interested in paying money that another is bound by law to pay, who pays it, is entitled to be reimbursed by that other.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-95","question":"A mill's broken crankshaft is given to a carrier to take to the makers as a pattern. The carrier is told nothing about the mill being idle without it, and delivers late. Can the mill owner recover the profits lost during the delay?","options":["Yes, all losses caused by the breach are recoverable","No: the loss of profit did not arise naturally and was not in the parties' contemplation","Yes, but only half","Only if the carrier was negligent"],"answer":1,"explanation":"Hadley v Baxendale: damages cover losses arising naturally from the breach or that both parties contemplated when contracting. Special circumstances not communicated make the loss too remote.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-96","question":"A contract states that ₹5 lakh is payable on breach. One party breaks it; the other's actual loss is ₹2 lakh. Under Section 74, what can the court award?","options":["Exactly ₹5 lakh, as agreed","Nothing, unless the loss exceeds ₹5 lakh","₹5 lakh plus actual loss","Reasonable compensation not exceeding ₹5 lakh, without the need to prove the exact loss"],"answer":3,"explanation":"Indian law does not distinguish strictly between penalty and liquidated damages: the aggrieved party gets reasonable compensation up to the stipulated amount, whether or not actual loss is proved, but not automatically the full sum.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-97","question":"On 1 March, A tells B he will not deliver the goods due on 1 June. What is B's position?","options":["B may treat the contract as ended and sue at once, or wait until 1 June","B must wait until 1 June before taking any action","The contract is automatically void","B can only claim specific performance"],"answer":0,"explanation":"An anticipatory breach lets the promisee rescind and sue immediately, or keep the contract alive until the due date (Section 39); if he waits, he takes the risk of supervening events.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-98","question":"B agreed to buy 1,000 units at ₹500 each but refused delivery on the due date, when the market price was ₹440. The seller resold a month later at ₹400. What damages can the seller recover?","options":["₹1,00,000","₹40,000","₹60,000","₹5,00,000"],"answer":2,"explanation":"Damages = (contract price − market price on the date of breach) × quantity = (500 − 440) × 1,000 = ₹60,000. The further fall to ₹400 is the seller's loss for not mitigating promptly.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-99","question":"A hires a hall for a concert, but the hall is destroyed by fire, through no one's fault, before the concert date. What happens to the contract?","options":["The hall owner must pay damages","It becomes void because performance has become impossible","A must still pay the rent","It is suspended until the hall is rebuilt"],"answer":1,"explanation":"Section 56: a contract to do an act that afterwards becomes impossible, through no fault of the promisor, becomes void (supervening impossibility, as in Taylor v Caldwell).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-100","question":"A owes B ₹1 lakh. A, B and C agree that B will accept C as his debtor instead of A. This is:","options":["Rescission","Alteration","Remission","Novation"],"answer":3,"explanation":"Substituting a new contract (here with a new party) for the old one is novation (Section 62); the original contract need not be performed.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-101","question":"A publisher commissions A to write a book for a series for ₹50,000. After A has written half the book, the publisher abandons the series. What can A claim?","options":["Reasonable payment for the work done, on a quantum meruit basis","Nothing, because the book was not completed","The full ₹50,000, but only after finishing the book","Only his out-of-pocket expenses"],"answer":0,"explanation":"When one party is prevented from completing performance by the other's breach, he can recover reasonable remuneration for what he has done (quantum meruit, as in Planche v Colburn).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-102","question":"A contract by which one party promises to save the other from loss caused by the conduct of the promisor or any other person is a contract of:","options":["Guarantee","Bailment","Indemnity","Agency"],"answer":2,"explanation":"Section 124 defines a contract of indemnity; a guarantee involves a promise to discharge a third person's liability on default.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-103","question":"In a contract of guarantee, the three parties are:","options":["Indemnifier, indemnity holder and creditor","Surety, principal debtor and creditor","Bailor, bailee and surety","Principal, agent and creditor"],"answer":1,"explanation":"The surety gives the guarantee, the principal debtor owes the money, and the creditor receives the guarantee.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-104","question":"B borrows from C, with A as surety. B defaults. C sues A without first suing B. Is this allowed?","options":["No, the creditor must first exhaust remedies against the debtor","Yes, because the surety's liability is co-extensive with the principal debtor's","Only if B is insolvent","Only with the court's permission"],"answer":1,"explanation":"Section 128 makes the surety's liability co-extensive with the debtor's. Unless the contract says otherwise, the creditor may proceed against the surety directly.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-105","question":"A gives C a continuing guarantee for goods C supplies to B, up to ₹5 lakh. B buys goods worth ₹2 lakh and then ₹1.5 lakh. A then revokes the guarantee by notice to C. Afterwards B buys a further ₹1 lakh. B defaults on everything. What is A's liability?","options":["₹4.5 lakh","₹5 lakh","Nil","₹3.5 lakh"],"answer":3,"explanation":"A continuing guarantee can be revoked for future transactions by notice (Section 130). A remains liable for transactions before revocation: 2 + 1.5 = ₹3.5 lakh, not for the ₹1 lakh supplied afterwards.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-106","question":"A guarantees that C will lend B ₹5 lakh repayable in 12 months. Without A's consent, C and B change the loan to ₹8 lakh repayable in 24 months. What is A's position?","options":["A is discharged as to transactions after the variance","A is liable for ₹8 lakh","A is liable for ₹5 lakh repayable in 24 months","A must consent before C can sue B"],"answer":0,"explanation":"Section 133: any variance in the terms between the creditor and principal debtor without the surety's consent discharges the surety as to transactions after the variance.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-107","question":"How many of these discharge a surety, wholly or partly? (1) The creditor releases the principal debtor. (2) The creditor merely refrains from suing the debtor for some time. (3) The creditor makes a binding agreement to give the debtor extra time, without the surety's consent. (4) The creditor loses a security that was given at the time of the guarantee.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1) Section 134 and (3) Section 135 discharge the surety; (4) discharges him to the extent of the value of the security lost (Section 141). (2) does not: mere forbearance to sue does not discharge the surety (Section 137).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-108","question":"A surety pays the whole debt to the creditor after the principal debtor defaults. What right does the surety get?","options":["Only a right to a share of the debtor's profits","None, because a guarantee is gratuitous","A right to sue the creditor","The creditor's rights against the debtor, including securities held (subrogation)"],"answer":3,"explanation":"On payment, the surety steps into the creditor's shoes (Section 140) and may recover the amount from the principal debtor (Section 145).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-109","question":"A, B and C separately guarantee the same debt with limits of ₹1 lakh, ₹2 lakh and ₹3 lakh, with no agreement among themselves. The debtor defaults on ₹4 lakh. How much does C bear?","options":["₹2 lakh","₹1.5 lakh","₹1.33 lakh","₹3 lakh"],"answer":1,"explanation":"Section 147: co-sureties bound in different sums pay equally as far as their limits allow. Equal shares would be ₹1.33 lakh each, but A's limit is ₹1 lakh; the remaining ₹3 lakh is shared equally by B and C: ₹1.5 lakh each. Sharing in proportion to limits (₹2 lakh) is wrong.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-110","question":"Which of these is a bailment?","options":["Leaving a car with a mechanic for repair","Depositing money in a savings account","Parking in a self-park lot while keeping the car keys","Buying goods on credit"],"answer":0,"explanation":"Bailment is delivery of goods for a purpose, to be returned or dealt with as directed. A bank deposit is a debt, not bailment of the same notes; keeping your keys means no delivery of possession.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-111","question":"A bailee takes the care of the goods that a prudent person would take of his own similar goods, but they are stolen by armed robbers. There is no special contract. Is the bailee liable?","options":["Yes, a bailee is an insurer of the goods","Yes, but only for half the value","No, because he took the care required of a bailee","Only if the goods were valuable"],"answer":2,"explanation":"Sections 151–152: a bailee must take the care of a man of ordinary prudence; having done so, he is not liable for loss in the absence of a special contract.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-112","question":"Which of these statements about liens are correct? (1) A tailor may keep a suit until he is paid for stitching it. (2) Without any agreement, a tailor may keep a suit to recover dues on earlier, already delivered suits. (3) Bankers have a general lien. (4) Wharfingers have a general lien.","options":["(1) and (3) only","(1), (3) and (4) only","(2), (3) and (4) only","All four"],"answer":1,"explanation":"(1) is a particular lien for skill and labour on the goods (Section 170). (2) would need a general lien, which only bankers, factors, wharfingers, attorneys of a High Court and policy brokers have, or one given by agreement (Section 171).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-113","question":"A mercantile agent in possession of goods with the owner's consent pledges them, in the ordinary course of business, to a pawnee who acts in good faith and has no notice of any lack of authority. Is the pledge valid?","options":["No, only the owner can pledge goods","Only if the owner later ratifies it","No, it is void as against the owner","Yes, it is as valid as if the owner had expressly authorised it"],"answer":3,"explanation":"Section 178 protects a good-faith pawnee who takes a pledge from a mercantile agent in possession with the owner's consent, acting in the ordinary course of business.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-114","question":"A pawns gold for a loan of ₹1,00,000 and defaults. After reasonable notice, the pawnee sells the gold for ₹1,30,000, incurring sale expenses of ₹5,000. What happens to the proceeds?","options":["The pawnee keeps the ₹30,000","₹30,000 is paid to the pawnor","₹1,25,000 is paid to the pawnor","₹25,000 is paid to the pawnor"],"answer":3,"explanation":"Section 176: on default and reasonable notice, the pawnee may sell; he recovers the debt and sale expenses, and any surplus goes to the pawnor: 1,30,000 − 1,00,000 − 5,000 = ₹25,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-115","question":"In agency, the person for whom the agent acts is called the:","options":["Principal","Bailor","Surety","Promisee"],"answer":0,"explanation":"An agent is employed to act for, or represent, another person, called the principal (Section 182).","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-116","question":"An agent exceeds his authority and buys two machines on the principal's behalf. The principal wants to ratify the purchase of one and reject the other, which were bought in one transaction. Can he?","options":["No: ratifying part of a transaction ratifies the whole of it","Yes, he may ratify any part he chooses","Yes, but he must pay the agent's commission","Only with the seller's consent"],"answer":0,"explanation":"Section 199: a person ratifying an unauthorised act done on his behalf ratifies the whole transaction of which it forms part.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-117","question":"A authorises B to sell A's land and to pay himself, out of the proceeds, a debt that A owes him. A later wants to revoke B's authority, and then A dies. What is the position?","options":["A can revoke at any time, and his death ends the agency","The authority cannot be revoked, and A's death does not end it, because B has an interest in the subject matter","Only A's legal heirs can revoke it","The agency ends when the debt becomes due"],"answer":1,"explanation":"Section 202: where the agent has an interest in the property that is the subject of the agency, the agency cannot be ended to the prejudice of that interest, even by the principal's death or insanity.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-118","question":"An agent contracts with a third party without disclosing that he acts for a principal. The third party later discovers the principal. Whom can the third party hold liable?","options":["Only the agent","Only the principal","Neither, because the contract is void","Either the agent or the principal"],"answer":3,"explanation":"With an undisclosed principal, the third party can enforce the contract against the agent, or against the principal on discovering him (Section 231 and the following provisions).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-119","question":"How many of these statements are correct? (1) A sub-agent acts under the control of the original agent. (2) The agent is responsible to the principal for the acts of a properly appointed sub-agent. (3) A properly appointed sub-agent is directly responsible to the principal for ordinary negligence. (4) A substituted agent, named with the principal's authority, becomes the principal's own agent.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are correct (Sections 191, 192 and 194). (3) is wrong: a sub-agent is responsible to the principal only for fraud or wilful wrong, otherwise only to the agent.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-120","question":"Which of these ordinarily ends an agency?","options":["The agent's change of address","A rise in the price of the goods","The death or insanity of the principal or the agent","The principal's failure to sign a letter"],"answer":2,"explanation":"Section 201: an agency ends on revocation, renunciation, completion of the business, death or insanity of either party, or the principal's insolvency (subject to the exception for agency coupled with interest).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-121","question":"Under the Sale of Goods Act, how does a 'sale' differ from an 'agreement to sell'?","options":["In a sale, ownership passes to the buyer at once; in an agreement to sell, it passes later or on fulfilment of conditions","In a sale, the price is paid later","An agreement to sell must be in writing","There is no difference"],"answer":0,"explanation":"A sale transfers property in the goods immediately; an agreement to sell becomes a sale when the time elapses or the conditions are met.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-122","question":"What remedy does a buyer have for a breach of warranty, as opposed to a breach of condition?","options":["He may reject the goods and claim damages","He may claim damages only, not reject the goods","He may only reject the goods","He has no remedy"],"answer":1,"explanation":"A condition is essential to the main purpose; its breach allows repudiation. A warranty is collateral; its breach gives only a claim for damages.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-123","question":"A buyer accepts goods under a contract that is not severable and later discovers a breach of a condition. What can he do (absent any contrary term)?","options":["Reject the goods and recover the price","Rescind the contract at any time","Nothing at all","Claim damages only, treating the breach of condition as a breach of warranty"],"answer":3,"explanation":"Section 13(2): once a buyer has accepted the goods under a non-severable contract, a breach of condition can be treated only as a breach of warranty.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-124","question":"In a sale by sample as well as by description, the goods must:","options":["Correspond with the sample only","Correspond with the description only","Correspond with both the sample and the description","Only be of merchantable quality"],"answer":2,"explanation":"Section 15: where goods are sold by sample as well as description, it is not enough that the bulk matches the sample if it does not also match the description.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-125","question":"A buyer asks a chemist for a hot-water bottle and relies on the chemist's choice. The bottle bursts on first use and injures her. Which is correct?","options":["The seller is liable: the purpose was made known, the buyer relied on his skill and the goods were unfit for it","No liability, because of caveat emptor","Liability only if the bottle carried a brand name","Only the manufacturer can be liable"],"answer":0,"explanation":"Section 16(1) implies a condition of fitness for purpose when the buyer makes the purpose known (it can be obvious, as here) and relies on the seller's skill or judgment, and the seller deals in such goods.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-126","question":"How many of these are implied in a contract of sale (unless excluded)? (1) A condition that the seller has the right to sell (2) A warranty that the buyer will enjoy quiet possession (3) A condition that the goods are fit for any purpose the buyer privately has in mind (4) A condition of merchantable quality where goods are bought by description from a seller who deals in such goods","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are implied (Sections 14 and 16(2)). (3) is not: fitness for purpose is implied only when the purpose is made known and the buyer relies on the seller.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-127","question":"A buys a specific car that is in a deliverable state; delivery and payment are fixed for next week. That night the car is destroyed by fire without the seller's fault. Who bears the loss?","options":["The seller, because the car was still with him","They share it equally","The insurer only","The buyer, because property, and with it the risk, passed when the contract was made"],"answer":3,"explanation":"Section 20: for an unconditional contract for specific goods in a deliverable state, property passes when the contract is made, even if payment and delivery are postponed; risk prima facie passes with property (Section 26).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-128","question":"A agrees to sell B a specific heap of rice at ₹40 a kg; the seller must weigh it to fix the price. Before it is weighed, the rice is destroyed by flood without anyone's fault. Who bears the loss?","options":["The buyer, because the goods were specific","The seller, because property does not pass until the goods are weighed and the buyer is told","They share it in proportion","Neither: the contract is voidable"],"answer":1,"explanation":"Section 22: where the seller must weigh, measure or test specific goods to fix the price, property passes only when that is done and the buyer has notice. Risk therefore stayed with the seller.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-129","question":"Goods are delivered to B on approval ('sale or return'). Before approving them, B pledges the goods with a moneylender. What is the effect?","options":["Property passes to B, as the pledge is an act adopting the transaction, and he is liable for the price","Nothing changes; B can still return the goods","The pledge is void","Property passes only when B pays"],"answer":0,"explanation":"Section 24: property passes on approval, on any other act adopting the transaction (such as pledging or selling the goods), or on retaining them beyond the fixed or a reasonable time.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-130","question":"Which of these is NOT an exception to the rule that no one can give a better title than he himself has?","options":["Sale by a mercantile agent in possession with the owner's consent","Sale by a seller who stays in possession after a sale","Sale by a person with a voidable title before it is rescinded","Sale by a thief to an innocent buyer for value"],"answer":3,"explanation":"The Act protects good-faith buyers in the first three situations. A thief has no title at all, so even an innocent buyer for value gets none.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-131","question":"Who is an 'unpaid seller' under the Sale of Goods Act?","options":["A seller who has received the whole price in cash","A seller paid by a cheque that was honoured","A seller who received a cheque that was later dishonoured","A seller paid in full by bank transfer"],"answer":2,"explanation":"Section 45: a seller is unpaid when the whole price has not been paid or tendered, or when a negotiable instrument received as conditional payment has been dishonoured.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-132","question":"When can an unpaid seller exercise the right of stoppage in transit?","options":["Whenever any part of the price is unpaid","When the buyer has become insolvent and the goods are still in transit","Only before the goods are handed to the carrier","Only if he holds the bill of lading"],"answer":1,"explanation":"Stoppage in transit (Section 50) is available only on the buyer's insolvency while the goods are with a carrier. Before handing over, the seller relies on his lien instead.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-133","question":"How many of these statements about an unpaid seller's rights are correct? (1) The lien depends on the seller keeping possession. (2) Stoppage in transit is available even if the buyer is solvent. (3) The lien is lost when the buyer lawfully obtains possession. (4) The lien is lost merely because the seller has obtained a court decree for the price.","options":["One","Two","Three","Four"],"answer":1,"explanation":"(1) and (3) are correct. (2) is wrong: stoppage needs insolvency. (4) is wrong: Section 49(2) says the seller does not lose his lien just because he has obtained a decree for the price.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-134","question":"At an auction that was not notified as subject to the seller's right to bid, the seller secretly employs a person to bid up the price. What can the buyer do?","options":["Nothing, as bidding by anyone is allowed","Only claim the difference in price","Report it but remain bound","Treat the sale as fraudulent"],"answer":3,"explanation":"Section 64: unless the right to bid is expressly reserved and notified, the seller may not bid or employ anyone to bid, and a sale in breach may be treated as fraudulent by the buyer.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-135","question":"A buyer ordered 100 units; the seller delivers 120. What may the buyer do?","options":["Accept 100 and reject 20, reject all 120, or accept all 120 at the contract rate","He must accept all 120","He must reject all 120","He may accept all 120 at a price he chooses"],"answer":0,"explanation":"Section 37 gives the buyer these choices when a larger quantity is delivered; if a smaller quantity is delivered, he may reject it or accept it and pay at the contract rate.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-136","question":"Which of these is NOT a negotiable instrument under the Negotiable Instruments Act, 1881?","options":["Promissory note","Bill of exchange","Cheque","Share certificate"],"answer":3,"explanation":"The Act names promissory notes, bills of exchange and cheques; a share certificate is evidence of title to shares, not a negotiable instrument under this Act.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-137","question":"A cheque is:","options":["A bill of exchange payable after a fixed period","A bill of exchange drawn on a specified banker and payable only on demand, including electronic and truncated cheques","A promissory note issued by a bank","Any written order to pay money"],"answer":1,"explanation":"Section 6 defines a cheque this way; it is always on a banker and always payable on demand.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-138","question":"X receives a cheque from Y as a birthday gift and takes it in good faith before it is due. Is X a holder in due course?","options":["Yes, because he took it in good faith","Yes, because it was before maturity","No, because he did not take it for consideration","Only if Y was the drawer"],"answer":2,"explanation":"A holder in due course must obtain the instrument for consideration, before maturity and without cause to believe there is any defect in the transferor's title (Section 9). A gift fails the consideration test.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-139","question":"How many of these statements are correct? (1) A holder in due course can get a better title than his transferor. (2) A holder who takes through a holder in due course and was not a party to any fraud has the same rights. (3) A holder in due course of a forged instrument can enforce it against the person whose signature was forged. (4) Every holder is presumed to be a holder in due course until the contrary is proved.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) (Section 53) and (4) (Section 118(g)) are correct. (3) is wrong: a forgery is a nullity and gives no title, even to a holder in due course.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-140","question":"A cheque has two parallel transverse lines with 'HDFC Bank Ltd' written between them. This is a:","options":["Special crossing: it will be paid only to HDFC Bank, as collecting banker","General crossing","Not-negotiable crossing","Open cheque"],"answer":0,"explanation":"Writing a banker's name across the cheque, with or without lines, is a special crossing (Section 124). Two lines alone would be a general crossing.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-141","question":"A cheque is dishonoured and the payee sends the statutory demand notice under Section 138, which the drawer receives on 5 March. By what date must the drawer pay to avoid the offence?","options":["17 March","20 March","1 April","4 April"],"answer":1,"explanation":"The drawer has 15 days from receipt of the notice: 5 March + 15 days = 20 March. If he fails, the cause of action arises the next day and the complaint must be filed within one month of that.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-142","question":"Notice of dishonour is NOT necessary to charge the drawer when:","options":["The drawee is a public-sector bank","The amount is small","The holder is a minor","The drawer has countermanded payment (stopped the cheque)"],"answer":3,"explanation":"Section 98 dispenses with notice in cases such as when the drawer has countermanded payment, when the party entitled has waived it, or when the party charged could suffer no damage from lack of notice.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-143","question":"In a promissory note, the person who promises to pay is called the:","options":["Drawer","Maker","Drawee","Endorsee"],"answer":1,"explanation":"A promissory note has a maker (who promises) and a payee. A bill of exchange has a drawer, a drawee and a payee.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-144","question":"A bill dated 15 January is payable two months after date. Three days of grace apply, and the resulting date is a public holiday. On what date is the bill due?","options":["17 March","18 March","19 March","15 March"],"answer":0,"explanation":"Two months after 15 January is 15 March; adding three days of grace gives 18 March. Because that day is a public holiday, the bill falls due on the preceding business day (Section 25): 17 March.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-145","question":"Which of these is NOT a material alteration of a negotiable instrument?","options":["Changing the date","Changing the amount","Converting a blank endorsement into a full endorsement","Changing the place of payment"],"answer":2,"explanation":"A holder may convert a blank endorsement into a full one (Section 49) without it being a material alteration. Changing the date, amount or place of payment without consent voids the instrument against non-consenting parties.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-146","question":"An endorser writes 'sans recourse' with his endorsement. What is the effect?","options":["He becomes liable to all later holders","The instrument stops being negotiable","He guarantees payment by the drawee","He excludes his own liability to later holders"],"answer":3,"explanation":"Section 52 lets an endorser exclude his own liability by express words such as 'sans recourse'; the instrument stays negotiable.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-147","question":"A cheque reads 'Pay Ramesh or order'. Ramesh endorses it by signing only his name on the back. To whom is it now payable?","options":["To the bearer","Only to Ramesh","Only to Ramesh's bank","To no one until a full endorsement is added"],"answer":0,"explanation":"An endorsement in blank (signature only) makes the instrument payable to bearer (Section 54), until it is converted into a full endorsement.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-148","question":"A signs a blank promissory note on adequately stamped paper and gives it to B to fill in ₹20,000. B fills in ₹50,000 (within the stamp's coverage) and negotiates it for value to C, a holder in due course. How much can C recover from A?","options":["₹20,000 only, the agreed amount","₹50,000, because the stamp covers that amount","Nothing, as the note was incomplete when signed","₹30,000, the excess"],"answer":1,"explanation":"Section 20 (inchoate stamped instruments): the signer is liable to a holder in due course for any amount filled in, up to the amount the stamp covers. As between A and B, only ₹20,000 was authorised.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-149","question":"A agrees to sell B a specific cargo of wheat on a ship. Unknown to both, the ship had already sunk with the cargo before the agreement. What is the effect?","options":["The seller must supply another cargo","The buyer must pay the price","The contract is voidable at the buyer's option","The agreement is void"],"answer":3,"explanation":"Section 7 of the Sale of Goods Act: a contract for specific goods that, without the seller's knowledge, have perished at the time of the contract is void.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-150","question":"If the price is not fixed by the contract or by any agreed method, the buyer must pay:","options":["A reasonable price","The price the seller demands","The cost price","Nothing, as the contract is void"],"answer":0,"explanation":"Section 9(2): where the price is not determined, the buyer pays a reasonable price, which depends on the circumstances of each case.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-151","question":"Which case established that a company is a legal person separate from its members, even when one person holds almost all its shares?","options":["Royal British Bank v Turquand","Ashbury Railway Carriage v Riche","Salomon v Salomon & Co","Hadley v Baxendale"],"answer":2,"explanation":"Salomon v Salomon & Co (1897) held that a duly incorporated company is a distinct person from its members, so Mr Salomon as a secured creditor ranked ahead of unsecured creditors.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-152","question":"What is the minimum number of members needed to form a private company (other than a one person company)?","options":["Two","Seven","One","Three"],"answer":0,"explanation":"A private company needs at least two members, a public company seven and a one person company one.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-153","question":"A company's articles allow directors to borrow if authorised by a general-meeting resolution. A lender, acting in good faith, lends to the company on the directors' word, but no resolution had been passed. Is the company bound?","options":["No, because the lender had constructive notice of the articles","Only if the shareholders ratify it","No, the loan is void","Yes, under the doctrine of indoor management, outsiders may assume internal procedures were complied with"],"answer":3,"explanation":"Royal British Bank v Turquand: an outsider who knows the articles permit the act need not check that internal formalities, such as passing a resolution, were actually carried out.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-154","question":"In which situation can an outsider NOT rely on the doctrine of indoor management?","options":["The company's internal resolution was passed late","The document he relied on was a forgery","The directors had not yet signed the minutes","The company had not filed its annual return"],"answer":1,"explanation":"The doctrine does not protect an outsider who knew of the irregularity, was put on enquiry by suspicious circumstances, or relied on a forged document, since a forgery is a nullity.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-155","question":"The doctrine of constructive notice means that a person dealing with a company is deemed to know:","options":["Its internal board minutes","The private agreements among its directors","The contents of its memorandum and articles, which are public documents","Its future business plans"],"answer":2,"explanation":"Once registered, the memorandum and articles are public documents, so outsiders are presumed to know their contents (indoor management protects them on internal matters).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-156","question":"A company enters into a contract wholly outside the objects in its memorandum. All the shareholders later pass a resolution ratifying it. What is the status of the contract?","options":["Void; an ultra vires act cannot be ratified even unanimously","Valid after unanimous ratification","Voidable at the company's option","Valid if the directors approved it"],"answer":0,"explanation":"Ashbury Railway Carriage v Riche: an act ultra vires the memorandum is void ab initio and cannot be ratified, even by all the shareholders.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-157","question":"At a general meeting, 600 votes are cast in favour of a resolution, 220 against and 300 members abstain. Which is correct?","options":["It passes as both an ordinary and a special resolution","It passes as an ordinary resolution but fails as a special resolution","It fails as both","It passes as a special resolution only"],"answer":1,"explanation":"Ordinary: votes for (600) exceed votes against (220). Special: votes for must be at least three times votes against, 3 × 220 = 660; 600 falls short. Abstentions are not counted.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-158","question":"A company's financial year ends on 31 March 2026, and its previous AGM was held on 20 August 2025. Without any extension, by when must its next AGM be held?","options":["30 September 2026","20 November 2026","31 December 2026","20 August 2026"],"answer":0,"explanation":"An AGM (other than the first) must be held within six months of the end of the financial year (30 September 2026) and within 15 months of the last AGM (20 November 2026). The earlier date, 30 September 2026, applies.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-159","question":"A company's articles provide for 11 directors, but two seats are vacant. Under Section 174, quorum is one-third of the total strength (a fraction counts as one) or two directors, whichever is higher, and vacant seats are not counted in total strength. What is the quorum?","options":["4","2","3","6"],"answer":2,"explanation":"Total strength = 11 − 2 vacancies = 9. One-third of 9 = 3, which is more than two, so the quorum is 3. Counting the vacant seats gives one-third of 11 = 3.67, rounded to 4.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-160","question":"What is the minimum number of directors a public company must have?","options":["One","Two","Seven","Three"],"answer":3,"explanation":"Under Section 149, a public company needs at least three directors, a private company two and a one person company one.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-161","question":"Which requirement does the Companies Act, 2013 impose on every company's board?","options":["At least one director must be a chartered accountant","At least one director must have stayed in India for at least 182 days in the financial year","All directors must be Indian citizens","At least half the directors must be independent"],"answer":1,"explanation":"Section 149(3) requires at least one resident director, meaning one who has stayed in India for 182 days or more during the financial year. Independent-director requirements apply to listed and prescribed companies.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-162","question":"A listed public company has 10 directors. At least one-third of the total directors must be independent, and any fraction is rounded up to one. What is the minimum number of independent directors?","options":["3","4","5","2"],"answer":1,"explanation":"One-third of 10 = 3.33; the fraction counts as one, so at least 4 independent directors are needed. Truncating to 3 is the usual error.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-163","question":"If a company's articles conflict with its memorandum, which prevails?","options":["The articles, being more detailed","The later document","Whichever the board chooses","The memorandum, because the articles are subordinate to it"],"answer":3,"explanation":"The memorandum is the charter defining the company's powers; the articles regulate internal management within those limits. A conflicting article is void to that extent.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-164","question":"A Section 8 company is formed for charitable objects. Which feature does it have?","options":["It must apply its profits to its objects and cannot pay dividends to members","It pays a fixed dividend to members","It must have at least seven members","It cannot own property"],"answer":0,"explanation":"A Section 8 company promotes objects such as charity, education or art, applies its income to those objects and is prohibited from paying dividends to its members.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-165","question":"A former employee bound by a valid non-compete covenant forms a company, controlled by him and his family, to solicit his old employer's customers. What will the court most likely do?","options":["Refuse relief, because the company is a separate person not bound by the covenant","Wind up the company","Award damages only against the family members","Lift the corporate veil and restrain both him and the company, as the company is a sham to evade his obligation"],"answer":3,"explanation":"Courts disregard the separate personality of a company used as a façade to evade an existing legal obligation (as in Gilford Motor Co v Horne).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-166","question":"Which element of the definition of partnership in Section 4 of the Indian Partnership Act reflects mutual agency?","options":["An agreement between persons","The business is carried on by all or any of them acting for all","Profits are shared","The business must be lawful"],"answer":1,"explanation":"'Carried on by all or any of them acting for all' means each partner is both an agent of the others and a principal, which is the true test of partnership.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-167","question":"An unregistered firm wants to sue a customer to recover money due under a contract. What is the position?","options":["It can sue freely","It can sue only in small-cause courts","It cannot sue the customer to enforce the contract, though the customer can sue the firm","It can sue only if all partners consent"],"answer":2,"explanation":"Section 69 bars an unregistered firm (and its partners on its behalf) from suing third parties to enforce contractual rights; third parties can still sue the firm, and partners can sue for dissolution or accounts.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-168","question":"Which of these can a partner do under his implied authority, without specific authority from the other partners?","options":["Buy goods of the kind the firm usually deals in, for its business","Submit a dispute of the firm to arbitration","Transfer immovable property belonging to the firm","Open a bank account for the firm in his own name"],"answer":0,"explanation":"Section 19(2) excludes arbitration, opening an account in his own name, compromising claims, transferring immovable property and similar acts from implied authority. Ordinary trading acts are within it.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-169","question":"How many of these statements are correct? (1) A person admitted as a partner is not liable for the firm's debts incurred before he joined. (2) A retiring partner remains liable to third parties for the firm's acts until public notice of his retirement is given. (3) A deceased partner's estate is liable for the firm's acts done after his death. (4) A person who holds himself out as a partner is liable to anyone who gave credit to the firm on that basis.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are correct (Sections 31, 32 and 28). (3) is wrong: under Section 35 the estate of a deceased partner is not liable for acts of the firm after his death.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-170","question":"In which situation is a firm compulsorily dissolved, without any court order?","options":["A partner becomes of unsound mind","The firm suffers a loss for one year","A partner transfers his share to an outsider","All the partners, or all but one, are adjudged insolvent"],"answer":3,"explanation":"Section 41: compulsory dissolution occurs on the insolvency of all, or all but one, partners, or when the business becomes unlawful. Unsoundness of mind is a ground for dissolution by the court (Section 44).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-171","question":"Under the LLP Act, 2008, what is the minimum requirement for designated partners?","options":["One designated partner","At least two designated partners, of whom at least one is resident in India","Seven designated partners","No designated partners are needed"],"answer":1,"explanation":"Every LLP must have at least two partners and at least two designated partners who are individuals, at least one of them resident in India.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-172","question":"How many of these statements about an LLP are correct? (1) It is a body corporate with perpetual succession. (2) A partner is personally liable for another partner's wrongful act. (3) There is no upper limit on the number of partners. (4) Mutual rights are governed by the LLP agreement, and where it is silent, by the First Schedule to the Act.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (3) and (4) are correct. (2) is wrong: a partner is not personally liable for another partner's wrongful act or misconduct, though he is liable for his own.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-173","question":"A minor admitted to the benefits of a partnership attains majority and does not give any public notice within six months. What is his position?","options":["He automatically ceases to be connected with the firm","He is liable only from the date of attaining majority","He may never become a partner","He becomes a partner and is personally liable for the firm's acts from the date he was admitted to its benefits"],"answer":3,"explanation":"Section 30: if he fails to give public notice of his election within six months, he becomes a partner and is personally liable for all acts of the firm since he was admitted to its benefits.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-174","question":"In a partnership at will, one partner wants to end the firm. What must he do?","options":["Give written notice to all the other partners of his intention to dissolve the firm","Obtain the consent of all partners","Apply to the court in every case","Wait until the firm makes a loss"],"answer":0,"explanation":"Section 43: a partnership at will may be dissolved by any partner giving notice in writing to all the other partners; it is dissolved from the date mentioned in the notice or the date of communication.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-175","question":"Company A holds 30% of Company B's shares but has the power to appoint and remove all of B's directors. Is B a subsidiary of A?","options":["No, because A holds less than half the shares","Yes, because A controls the composition of B's board","Only if A also holds preference shares","Only if B's articles say so"],"answer":1,"explanation":"Under Section 2(87), control of the composition of the board of directors is enough to make a company a subsidiary, regardless of shareholding.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
];

export default questions;
